fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(n:&str,v:&Value){fs::write(format!("{R}/{n}"),serde_json::to_vec_pretty(v).unwrap()).unwrap();}
fn main(){assert!(!Path::new(&format!("{R}/source")).exists());let mp=format!("{Z}/docs/benchmarks/2026-11-11-phi-grain-parent176/artifacts/production-source-manifest.json");let m:Value=serde_json::from_slice(&fs::read(&mp).unwrap()).unwrap();let originals=m["source_files_sha256"].as_object().unwrap();assert_eq!(originals.len(),176);
for(rel,h)in originals{let mut p=format!("{Z}/{rel}");if hash(&p)!=h.as_str().unwrap(){assert!(["crates/zopro-core/src/lib.rs","crates/zopro-core/build.rs"].contains(&rel.as_str()));p=format!("/home/ubuntu/src/zopro-perf-work/bounded-gather-sdk177/accepted-source/{rel}");}assert_eq!(hash(&p),h.as_str().unwrap());let dest=format!("{R}/source/{rel}");fs::create_dir_all(Path::new(&dest).parent().unwrap()).unwrap();fs::copy(p,dest).unwrap();}
let parent="crates/zopro-core/src/msm/g2_borrowed.rs";let p=format!("{R}/source/{parent}");let mut s=fs::read_to_string(&p).unwrap();
let old="        let x = Fq2::lanes_sub(&Fq2::lanes_square(&slope), &Fq2::lanes_add(&ax, &bx));\n        let y = Fq2::lanes_sub(&Fq2::lanes_mul(&slope, &Fq2::lanes_sub(&ax, &x)), &ay);";assert_eq!(s.matches(old).count(),1);
let original=format!("{{\n{old}\n        (x,y)\n        }}");let replacement=format!("        let (x,y) = {{\n            #[cfg(zopro_g2_coordinate_leaf)]\n            {{ if FAST {{ coordinate_leaf::finish(&ax,&ay,&bx,&slope) }} else {original} }}\n            #[cfg(not(zopro_g2_coordinate_leaf))]\n            {original}\n        }};");
s=s.replace(old,&replacement);let suffix="\n#[cfg(zopro_g2_coordinate_leaf)]\nmod coordinate_leaf;\n";s.push_str(suffix);assert_eq!(hash(&p),originals[parent]);assert_eq!(format!("{:x}",Sha256::digest(s.strip_suffix(suffix).unwrap().replace(&replacement,old).as_bytes())),originals[parent]);fs::write(p,s).unwrap();
let leaf="crates/zopro-core/src/msm/g2_borrowed/coordinate_leaf.rs";let to=format!("{R}/source/{leaf}");fs::create_dir_all(Path::new(&to).parent().unwrap()).unwrap();fs::copy(format!("{R}/coordinate_leaf.rs"),to).unwrap();
let tests="crates/zopro-core/src/msm/affine_offset_caller.rs";fs::copy(format!("{OLD}/source/{tests}"),format!("{R}/source/{tests}")).unwrap();
let testdecl="\n#[cfg(all(test,feature=\"ifma8\",target_arch=\"x86_64\",target_feature=\"avx512ifma\",target_feature=\"avx512vl\",target_feature=\"avx512dq\",not(no_ifma)))]\nmod affine_offset_caller;\n";
let p=format!("{R}/source/crates/zopro-core/src/msm.rs");let mut s=fs::read_to_string(&p).unwrap();s.push_str(testdecl);fs::write(p,s).unwrap();
let mut pins=BTreeMap::new();let mut changed=Vec::new();for(rel,h)in originals{let p=format!("{R}/source/{rel}");let actual=hash(&p);if actual!=h.as_str().unwrap(){changed.push(rel);}pins.insert(p,actual);}assert_eq!(changed.len(),2);for rel in[leaf,tests]{let p=format!("{R}/source/{rel}");pins.insert(p.clone(),hash(&p));}
save("source-audit.json",&json!({"base_manifest":mp,"base_manifest_sha256":hash(&mp),"base_files":176,"unchanged_originals":174,"changed_originals":changed,"added_files":[leaf,tests],"reversible_parent_edit":{"file":parent,"old":old,"new":replacement,"suffix":suffix},"test_only_msm_suffix":testdecl,"inherited_test_adapter_sha256":hash(format!("{R}/source/{tests}")),"field_sources_exact":true,"production_changed":false}));
let flags=fs::read_to_string(format!("{OLD}/control-flags.txt")).unwrap().replace(" --check-cfg=cfg(zopro_g1_affine_offset)","").replace(" --check-cfg=cfg(zopro_affine_offset_diagnostics)","")+" --check-cfg=cfg(zopro_g2_coordinate_leaf)";
fs::write(format!("{R}/control-flags.txt"),&flags).unwrap();fs::write(format!("{R}/candidate-flags.txt"),format!("{flags} --cfg zopro_g2_coordinate_leaf")).unwrap();
for rel in["driver.rs","support/perf.rs"]{let to=format!("{R}/{rel}");fs::create_dir_all(Path::new(&to).parent().unwrap()).unwrap();fs::copy(format!("{OLD}/{rel}"),to).unwrap();}
fs::write(format!("{R}/native.rs"),fs::read_to_string(format!("{OLD}/native.rs")).unwrap().replace(OLD,R)).unwrap();
for label in["control","candidate","portable"]{let mut p:Value=serde_json::from_str(&fs::read_to_string(format!("{OLD}/{label}-plan.json")).unwrap().replace(OLD,R)).unwrap();for step in p["steps"].as_array_mut().unwrap(){if step["environment"].is_object(){if label=="portable"{let flags=step["environment"]["RUSTFLAGS"].as_str().unwrap().replace("zopro_g1_affine_offset","zopro_g2_coordinate_leaf");step["environment"]["RUSTFLAGS"]=json!(flags);}else{step["environment"]["RUSTFLAGS"]=json!(fs::read_to_string(format!("{R}/{label}-flags.txt")).unwrap());}}}save(&format!("{label}-plan.json"),&p);}
for rel in["prepare.rs","design.md","source-audit.json","coordinate_leaf.rs","driver.rs","support/perf.rs","native.rs","control-plan.json","candidate-plan.json","portable-plan.json","control-flags.txt","candidate-flags.txt","original-code.json","inspect.rs"]{let p=format!("{R}/{rel}");pins.insert(p.clone(),hash(p));}save("build-pins.json",&json!(pins));println!("Prepared coordinate leaf:174originalsexact,1releasecalleredit+1testdeclaration,2addedfiles. No SDK executed.");}
